export type Employee = {
  id: string;
  name: string;
  department: string;
  /** Индекс в LEVEL_LABELS: 0 = Junior … 3 = Lead */
  level: number;
  /** Зарплата в рублях */
  salary: number;
  /** Дата найма в формате YYYY-MM-DD */
  hiredAt: string;
};

export const LEVEL_LABELS = ['Junior', 'Middle', 'Senior', 'Lead'] as const;

